{
  "timeout": 300,
  "steps": [
    {
      "id": "inbox",
      "kind": "stage",
      "objective": "Triage a raw inbox entry into a work item.",
      "moves": "",
      "inputs": [],
      "produces": "",
      "gates": [],
      "bindings": {
        "bind": []
      }
    },
    {
      "id": "request",
      "kind": "stage",
      "objective": "Capture what is being asked for, and why.",
      "moves": "",
      "inputs": [],
      "produces": "initial-request.md",
      "gates": [],
      "bindings": {
        "bind": []
      }
    },
    {
      "id": "spec",
      "kind": "stage",
      "objective": "Decide what to build and why, before deciding how.",
      "moves": "",
      "inputs": [
        "initial-request.md",
        "intake.md"
      ],
      "produces": "spec.md",
      "gates": [],
      "bindings": {
        "bind": [
          {
            "skill": "superpowers:brainstorming"
          }
        ]
      }
    },
    {
      "id": "plan",
      "kind": "stage",
      "objective": "Decide how to build it, in ordered, checkable steps.",
      "moves": "",
      "inputs": [
        "initial-request.md",
        "intake.md",
        "spec.md"
      ],
      "produces": "plan.md",
      "gates": [],
      "bindings": {
        "bind": []
      }
    },
    {
      "id": "implement",
      "kind": "stage",
      "objective": "Build it, and record what actually happened.",
      "moves": "",
      "inputs": [
        "spec.md",
        "plan.md",
        "rework.md"
      ],
      "produces": "outcome.md",
      "gates": [],
      "bindings": {
        "bind": []
      }
    },
    {
      "id": "verify",
      "kind": "stage",
      "objective": "Obtain the user's acceptance decision on the finished work.",
      "moves": "",
      "inputs": [
        "spec.md",
        "outcome.md"
      ],
      "produces": "refined-outcome.md (accepted) or rework.md (rejected)",
      "gates": [],
      "bindings": {
        "bind": []
      }
    },
    {
      "id": "postmortem",
      "kind": "stage",
      "objective": "Find which stage first missed a problem. Out-of-band: legal in review or after completion, and never changes status.",
      "moves": "",
      "inputs": [
        "initial-request.md",
        "intake.md",
        "spec.md",
        "plan.md",
        "outcome.md",
        "refined-outcome.md",
        "rework.md"
      ],
      "produces": "post-mortem.md",
      "gates": [],
      "bindings": {
        "bind": []
      }
    },
    {
      "id": "start",
      "kind": "transition",
      "objective": "Begin implementation.",
      "moves": "backlog \u2192 active",
      "inputs": [],
      "produces": "",
      "gates": [
        "unresolved blockers",
        "the initiative epic must be active"
      ],
      "bindings": {
        "pre": [],
        "post": []
      }
    },
    {
      "id": "submit",
      "kind": "transition",
      "objective": "Hand finished work to verification.",
      "moves": "active \u2192 review",
      "inputs": [],
      "produces": "",
      "gates": [],
      "bindings": {
        "pre": [],
        "post": []
      }
    },
    {
      "id": "rework",
      "kind": "transition",
      "objective": "Send rejected work back for another pass.",
      "moves": "review \u2192 active",
      "inputs": [],
      "produces": "",
      "gates": [
        "refined-outcome.md must be absent"
      ],
      "bindings": {
        "pre": [],
        "post": []
      }
    },
    {
      "id": "complete",
      "kind": "transition",
      "objective": "Close the item as shipped.",
      "moves": "review | active \u2192 completed",
      "inputs": [],
      "produces": "",
      "gates": [
        "unresolved blockers",
        "open initiative children",
        "declared capabilities reconciled",
        "worktree merge-back",
        "--confirm"
      ],
      "bindings": {
        "pre": [],
        "post": []
      }
    },
    {
      "id": "discard",
      "kind": "transition",
      "objective": "Close the item without shipping. Reached as `complete --resolution <not-done>`, not a verb of its own.",
      "moves": "backlog | active | review \u2192 discarded",
      "inputs": [],
      "produces": "",
      "gates": [
        "--confirm"
      ],
      "bindings": {
        "pre": [],
        "post": []
      }
    },
    {
      "id": "auto-delete",
      "kind": "transition",
      "objective": "Remove a resolved item from the store, after it has been committed where it landed. Reached as part of a resolving transition under `work.retain: <status>: false`, not as a verb of its own; `tcw work delete` finishes one a failed `pre` binding left pending.",
      "moves": "completed | discarded \u2192 (removed)",
      "inputs": [],
      "produces": "",
      "gates": [
        "work.retain must say the status is not kept"
      ],
      "bindings": {
        "pre": [],
        "post": []
      }
    }
  ]
}
